"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisPricingContent } from "./components/pricing/content";
import View1 from "./components/pricing/variants/02-shared-benefits";
const views={"shared-benefits":View1};
export type { ArtemisPricingBenefits, ArtemisPricingBilling, ArtemisPricingCalculator, ArtemisPricingContent, ArtemisPricingImage, ArtemisPricingLink, ArtemisPricingPlan, ArtemisPricingTier } from "./components/pricing/content";
export interface ArtemisPricingProps {className?:string;variant?:"shared-benefits";/** The words on the pricing section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisPricingContent>;}
export function ArtemisPricing({className,variant="shared-benefits",content}:ArtemisPricingProps){const View=views[variant];return <ArtemisScope className={`art:[&>*]:mx-auto ${className??""}`}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisPricingLink {
  label: string;
  href: string;
}

/** A picture shown as content. */
export interface ArtemisPricingImage {
  src: string;
  alt: string;
}

/** The two options of the billing switch. */
export interface ArtemisPricingBilling {
  /** The monthly option. */
  monthly: string;
  /** The yearly option. */
  yearly: string;
  /** What paying yearly saves, such as "Save 20%". command-deck and ledger add it to the yearly option, plans-grid shows it beside it. ledger's estimate takes 20% off whatever this says. */
  saving?: string;
}

/** A usage level of a plan, with its own price. */
export interface ArtemisPricingTier {
  /** The tier's option in the plan's switch, such as "5x". */
  label: string;
  /** Replaces the plan's `price` while the tier is chosen. */
  price?: number;
  /** Replaces the plan's `yearlyPrice` while the tier is chosen. */
  yearlyPrice?: number;
  /** Replaces the plan's `description` while the tier is chosen. */
  description?: string;
  /** Replaces the plan's `cta` while the tier is chosen. */
  cta?: ArtemisPricingLink;
}

/** A plan and its price. */
export interface ArtemisPricingPlan {
  /** A short id such as "pro". shared-benefits uses it as the plan picker's value, or the name when left out. */
  id?: string;
  /** All layouts. */
  name: string;
  /** Who the plan is for. All layouts but aurora-flow. */
  description?: string;
  /** The price per month, or the one-off price, as a number of `currency`. All layouts; ledger adds seats to it. */
  price?: number;
  /** The price per month when billed yearly. ai, shared-benefits, command-deck and plans-grid show it while yearly is chosen, and keep `price` without it. */
  yearlyPrice?: number;
  /** Words shown instead of the price, such as "Free" or "Custom pricing". All layouts. */
  priceLabel?: string;
  /** An earlier price, struck through beside the price. plans-grid. */
  compareAtPrice?: number;
  /** After the price, such as "/ month" or "one time". All layouts. */
  period?: string;
  /** A short line about the price, such as "Billed monthly": under the price in ai, shared-benefits and command-deck, at the foot of the card in plans-grid. With `yearlyNote`, it shows only while monthly is chosen. */
  note?: string;
  /** The line in place of `note` while yearly is chosen, such as "{total} billed yearly"; "{total}" becomes the yearly total with its currency. ai, shared-benefits, command-deck and plans-grid. */
  yearlyNote?: string;
  /** A small tag beside the name, such as "Best value". aurora-flow, visual-plans and plans-grid. */
  badge?: string;
  /** Marks the plan to recommend. ai, visual-plans, command-deck and plans-grid draw it apart; shared-benefits and ledger open on it; aurora-flow shows it. */
  featured?: boolean;
  /** A small heading over the features. ai and visual-plans. */
  featuresTitle?: string;
  /** What the plan includes. All layouts; shared-benefits lists them on one line. */
  features: string[];
  /** The plan's button. All layouts; shared-benefits and ledger show the chosen plan's. "{billing}" in the href becomes the chosen period, "monthly" or "annual" ("yearly" in shared-benefits; always "monthly" in layouts without a switch). */
  cta: ArtemisPricingLink;
  /** Usage levels with their own price, shown as a switch on the plan. ai. */
  tiers?: ArtemisPricingTier[];
  /** Seats the price includes. ledger. */
  includedSeats?: number;
  /** The monthly price of each seat after `includedSeats`. ledger. */
  seatPrice?: number;
}

/** What every plan includes. */
export interface ArtemisPricingBenefits {
  /** A small line over the title. */
  badge?: string;
  title: string;
  items: string[];
}

/** The words on ledger's seat calculator and estimate. The maths stays in the layout. */
export interface ArtemisPricingCalculator {
  /** Before each plan's price in the plan picker, such as "From". */
  from: string;
  /** Before the chosen plan's name, over its details, such as "Selected". */
  selected: string;
  /** After the chosen plan's price, such as "/ base". */
  base: string;
  /** Over the seat count, such as "Team size". */
  teamSize: string;
  /** After the seat count, such as "seats". */
  seats: string;
  /** After the seats a plan includes, such as "included". */
  included: string;
  /** After the price of each extra seat, such as "thereafter". */
  thereafter: string;
  /** Before the chosen plan's name, over the estimate, such as "Estimate". */
  estimate: string;
  /** A tag under the estimate's title, such as "Updates live". */
  live: string;
  /** The estimate's line for the plan's price, such as "Base plan". */
  basePlan: string;
  /** After the number of included seats, such as "included seats". */
  includedSeats: string;
  /** After the number of extra seats, such as "additional seats". */
  extraSeats: string;
  /** The estimate's line for the yearly discount, such as "Annual discount". */
  discount: string;
  /** Over the total, such as "Due monthly". */
  total: string;
  /** After the total, such as "USD". */
  currencyCode: string;
}

/** The words on an Artemis pricing section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisPricingContent {
  /** A short line over the headline. ai, aurora-flow, visual-plans, command-deck, ledger and plans-grid. */
  badge?: string;
  /** All layouts. */
  headline: string;
  /** A sentence or two under the headline. All layouts but ledger. */
  subhead?: string;
  /** The sign before every price, such as "$". All layouts. */
  currency: string;
  /** The billing switch. ai, shared-benefits, command-deck, ledger and plans-grid. */
  billing?: ArtemisPricingBilling;
  /** All layouts. aurora-flow shows the featured plan, or the first; visual-plans looks best with two, the others with three. */
  plans: ArtemisPricingPlan[];
  /** A heading over the plan picker. shared-benefits. */
  plansTitle?: string;
  /** What every plan includes, beside the plan picker. shared-benefits. */
  benefits?: ArtemisPricingBenefits;
  /** The picture over the benefits. shared-benefits. */
  image?: ArtemisPricingImage;
  /** A line of small print: under the plans in ai and plans-grid, under the subhead in aurora-flow, under the button in ledger. */
  footnote?: string;
  /** The words on the seat calculator. ledger. */
  calculator?: ArtemisPricingCalculator;
}

"use client";
// @zeus-internal
import { useId, useState } from "react";
import { motion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { PricingTabs, PriceNumber } from "./02-shared-benefits/controls";
import type { ArtemisPricingContent, ArtemisPricingPlan } from "../content";
const DEFAULT = {
    headline: "The same great tools. Your kind of space.",
    subhead: "Every plan starts with the essentials. Choose the room you need to make something worth sharing.",
    currency: "$",
    billing: { monthly: "Monthly", yearly: "Yearly" },
    image: { src: "/assets/artemis/c900f3f4b9ce7c6d88ee.webp", alt: "Painted coastal cliffs overlooking a calm blue inlet" },
    benefits: {
        badge: "Always included",
        title: "A good foundation, on every plan.",
        items: ["All creative tools, from day one", "Unlimited guests and shared links", "Version history and automatic backups", "Export your work in original quality", "Personal support when you need it"],
    },
    plansTitle: "Make it yours.",
    plans: [
        { id: "solo", name: "Solo", description: "For your own ideas", price: 16, yearlyPrice: 12, period: "/ month", note: "Billed monthly", yearlyNote: "{total} billed yearly", features: ["1 person", "10 active projects", "25 GB storage"], cta: { label: "Continue with Solo", href: "/signup?plan=solo&billing={billing}" } },
        { id: "studio", name: "Studio", description: "For a small, focused team", price: 48, yearlyPrice: 36, period: "/ month", note: "Billed monthly", yearlyNote: "{total} billed yearly", features: ["5 people", "50 active projects", "100 GB storage"], cta: { label: "Continue with Studio", href: "/signup?plan=studio&billing={billing}" }, featured: true },
        { id: "collective", name: "Team E", description: "For bigger collaborations", price: 96, yearlyPrice: 72, period: "/ month", note: "Billed monthly", yearlyNote: "{total} billed yearly", features: ["15 people", "Unlimited projects", "500 GB storage"], cta: { label: "Continue with Team E", href: "/signup?plan=collective&billing={billing}" } },
    ],
} satisfies ArtemisPricingContent;
export default function PricingSharedBenefits({ content }: { content?: Partial<ArtemisPricingContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const plans: ArtemisPricingPlan[] = copy.plans;
    const id = useId();
    const [selected, setSelected] = useState(() => Math.max(0, plans.findIndex(option => option.featured)));
    const [billing, setBilling] = useState("monthly");
    const yearly = billing === "yearly";
    const amount = (plan: ArtemisPricingPlan) => (yearly ? plan.yearlyPrice : undefined) ?? plan.price ?? 0;
    const plan = plans[selected] ?? plans[0];
    const price = amount(plan);
    return (<>
      <section className="art:w-full art:bg-background art:px-6 art:py-12 art:text-foreground art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:py-16">
        <div className="art:mx-auto art:max-w-5xl">
          <div className="art:mb-9 art:max-w-2xl">
            <h2 className="art:text-balance art:text-4xl art:font-medium art:tracking-tight">
              {copy.headline}
            </h2>
            {copy.subhead && <p className="art:mt-4 art:max-w-xl art:text-sm art:leading-6 art:text-muted-foreground art:@min-[640px]/artemis:text-base">
              {copy.subhead}
            </p>}
          </div>
          <div className="art:grid art:overflow-hidden art:rounded-3xl art:@min-[1024px]/artemis:grid-cols-2">
            <div className="art:min-w-0 art:p-5 art:@min-[640px]/artemis:p-7">
              {copy.image && <div className="art:overflow-hidden art:rounded-2xl">
                <img src={copy.image.src} alt={copy.image.alt} loading="lazy" className="art:aspect-[2/1] art:w-full art:object-cover art:dark:brightness-75"/>
              </div>}
              {copy.benefits && <div className="art:px-1 art:pb-2 art:pt-7">
                {copy.benefits.badge && <p className="art:mb-2 art:text-xs art:text-muted-foreground">
                  {copy.benefits.badge}
                </p>}
                <h3 className="art:text-xl art:font-medium art:tracking-tight">
                  {copy.benefits.title}
                </h3>
                <ul className="art:mt-6 art:space-y-4">
                  {copy.benefits.items.map((item, index) => <li key={index} className="art:flex art:gap-3 art:text-sm art:leading-5 art:text-muted-foreground">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:mt-0.5 art:size-4 art:shrink-0 art:text-foreground" aria-hidden="true">
                      <path d="M20 6 9 17l-5-5"/>
                    </svg>
                    {item}
                  </li>)}
                </ul>
              </div>}
            </div>
            <div className="art:min-w-0 art:p-6 art:@min-[640px]/artemis:p-8">
              <div className="art:mb-6 art:flex art:flex-wrap art:items-center art:justify-between art:gap-4">
                {copy.plansTitle && <h3 className="art:text-xl art:font-medium">
                  {copy.plansTitle}
                </h3>}
                {copy.billing && <div>
                  <PricingTabs label="Billing period" className="art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1" buttonClassName="art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:px-3.5 art:py-1.5 art:font-medium art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none art:rounded-full art:h-8 art:text-xs art:focus-visible:outline-2 art:focus-visible:outline-offset-2 art:focus-visible:outline-ring" value={billing} onChange={setBilling} options={[{ value: "monthly", label: copy.billing.monthly }, { value: "yearly", label: copy.billing.yearly }]}/>
                </div>}
              </div>
              <fieldset className="art:space-y-3">
                <legend className="art:sr-only">
                  {"Choose your plan"}
                </legend>
                {plans.map((option, index) => <label key={index} className="art:relative art:block art:cursor-pointer">
                  <input type="radio" className="art:peer art:sr-only" name={id} checked={selected === index} value={option.id ?? option.name} onChange={() => setSelected(index)}/>
                  <span className={`art:flex art:items-center art:gap-4 art:rounded-2xl art:border art:border-border art:p-4 art:transition-colors art:peer-focus-visible:outline-2 art:peer-focus-visible:outline-offset-2 art:peer-focus-visible:outline-ring ${selected === index ? "art:bg-muted" : "art:bg-background"}`}>
                    <span aria-hidden="true" className={`art:grid art:size-5 art:shrink-0 art:place-items-center art:rounded-full art:border art:transition-colors ${selected === index ? "art:border-foreground" : "art:border-border"}`}>
                      <span className={`art:size-2.5 art:rounded-full art:bg-foreground art:transition-transform art:motion-reduce:transition-none ${selected === index ? "art:scale-100" : "art:scale-0"}`}/>
                    </span>
                    <span className="art:min-w-0 art:flex-1">
                      <span className="art:block art:text-sm art:font-medium">
                        {option.name}
                      </span>
                      {option.description && <span className="art:mt-1 art:block art:text-xs art:text-muted-foreground">
                        {option.description}
                      </span>}
                    </span>
                    <span className="art:shrink-0 art:text-right">
                      <span className="art:block art:text-base art:font-medium art:tabular-nums">
                        {option.priceLabel ?? `${copy.currency}${amount(option)}`}
                      </span>
                      {option.priceLabel === undefined && option.period && <span className="art:text-xs art:text-muted-foreground">
                        {option.period}
                      </span>}
                    </span>
                  </span>
                </label>)}
              </fieldset>
              <div className="art:mt-6 art:border-t art:border-border art:pt-5">
                <p className="art:mb-3 art:text-xs art:leading-5 art:text-muted-foreground">
                  {plan.features.join(" \u00B7 ")}
                </p>
                <div className="art:flex art:flex-wrap art:items-end art:gap-1">
                  <span className="art:inline-flex art:items-end art:font-sans art:text-foreground art:tabular-nums art:text-4xl art:font-medium art:tracking-tight">
                    {plan.priceLabel ?? <>
                    <span className="art:self-start art:pt-[0.12em] art:text-base art:text-muted-foreground">
                      {copy.currency}
                    </span>
                    <PriceNumber value={price}/>
                    </>}
                  </span>
                  {plan.priceLabel === undefined && plan.period && <span className="art:pb-2 art:text-xs art:text-muted-foreground">
                    {plan.period}
                  </span>}
                </div>
                <p className="art:mt-1 art:text-xs art:text-muted-foreground">
                  {yearly && plan.yearlyNote !== undefined ? plan.yearlyNote.replace("{total}", `${copy.currency}${Math.round(price * 1200) / 100}`) : plan.note}
                </p>
                <motion.a whileHover={{ scale: 1.01 }} whileTap={{ scale: 0.98 }} transition={{ duration: 0.2, ease: ARTEMIS_EASE_OUT }} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-5 art:h-9 art:w-full art:rounded-full" href={plan.cta.href.split("{billing}").join(billing)} tabIndex={0}>
                  {plan.cta.label}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                    <path d="M5 12h14"/>
                    <path d="m12 5 7 7-7 7"/>
                  </svg>
                </motion.a>
              </div>
            </div>
          </div>
        </div>
      </section>
    </>);
}

// @zeus-internal
export { ArtemisPricingTabs as PricingTabs } from "../../../../lib/pricing-tabs";
export { ArtemisPriceNumber as PriceNumber } from "../../../../lib/price-number";

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "./ease";
export function ArtemisPriceNumber({ value }: { value: number }) {
  const reduce = useReducedMotion() === true;
  const text = String(value);
  return (
    <span className="art:relative art:inline-flex art:h-[1.24em] art:items-center art:overflow-hidden art:px-[0.06em] art:align-bottom">
      <span className="art:sr-only">{text}</span>
      <span aria-hidden className="art:invisible">
        {text}
      </span>
      <AnimatePresence initial={false}>
        <motion.span
          key={text}
          aria-hidden
          className="art:absolute art:inset-y-0 art:right-[0.06em] art:left-[0.06em] art:flex art:items-center art:leading-[1.1]"
          initial={reduce ? { opacity: 0 } : { opacity: 0, y: "55%", filter: "blur(6px)" }}
          animate={{ opacity: 1, y: "0%", filter: "blur(0px)" }}
          exit={reduce ? { opacity: 0 } : { opacity: 0, y: "-55%", filter: "blur(6px)" }}
          transition={{ duration: reduce ? 0 : 0.32, ease: ARTEMIS_EASE_OUT }}
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

"use client";
// @zeus-internal
import { ArtemisSegmentedTabs } from "../foundations/segmented-tabs";
export function ArtemisPricingTabs({
  label,
  className,
  buttonClassName,
  value,
  onChange,
  options,
}: {
  label: string;
  className: string;
  buttonClassName: string;
  value: string;
  onChange: (value: string) => void;
  options: { value: string; label: string }[];
}) {
  return (
    <ArtemisSegmentedTabs
      layout="position"
      roving
      items={options}
      value={value}
      onValueChange={onChange}
      ariaLabel={label}
      listClassName={className}
      buttonClassName={buttonClassName}
    />
  );
}
